#define NOMINMAX
#include <windows.h>
#include <winternl.h>
#include <cstddef>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
struct Handle { HANDLE value; ~Handle(){if(value && value!=INVALID_HANDLE_VALUE)CloseHandle(value);} };
HANDLE directory(const std::wstring& path) {return CreateFileW(path.c_str(),FILE_LIST_DIRECTORY|FILE_READ_ATTRIBUTES|SYNCHRONIZE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT|FILE_FLAG_OPEN_NO_RECALL,nullptr);}
bool same(HANDLE a,HANDLE b) { FILE_ID_INFO x{},y{};return GetFileInformationByHandleEx(a,FileIdInfo,&x,sizeof(x)) && GetFileInformationByHandleEx(b,FileIdInfo,&y,sizeof(y)) && x.VolumeSerialNumber==y.VolumeSerialNumber && std::memcmp(&x.FileId,&y.FileId,16)==0; }
void dotdot(HANDLE child,HANDLE parent,const char* label) {
 WCHAR text[]=L"..";UNICODE_STRING name{};name.Length=4;name.MaximumLength=4;name.Buffer=text;
 OBJECT_ATTRIBUTES attributes{};attributes.Length=sizeof(attributes);attributes.RootDirectory=child;attributes.ObjectName=&name;
 IO_STATUS_BLOCK io{};HANDLE raw=nullptr;
 const NTSTATUS status=NtCreateFile(&raw,FILE_LIST_DIRECTORY|FILE_READ_ATTRIBUTES|SYNCHRONIZE,&attributes,&io,nullptr,0,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,FILE_OPEN,FILE_OPEN_REPARSE_POINT|FILE_OPEN_NO_RECALL|FILE_SYNCHRONOUS_IO_NONALERT,nullptr,0);
 Handle held{raw};std::printf("{\"case\":\"%s\",\"status\":\"%08lx\",\"parent_same\":%s}\n",label,static_cast<unsigned long>(status),status>=0 && raw && raw!=INVALID_HANDLE_VALUE && same(raw,parent)?"true":"false");
}
void enumerate(HANDLE child,HANDLE parent) {
 alignas(8) unsigned char buffer[65536]{};
 if(!GetFileInformationByHandleEx(child,FileIdExtdDirectoryRestartInfo,buffer,sizeof(buffer))) {std::printf("{\"enumeration_error\":%lu}\n",GetLastError());return;}
 FILE_ID_INFO expected{};if(!GetFileInformationByHandleEx(parent,FileIdInfo,&expected,sizeof(expected)))return;
 std::size_t at=0;
 for(int i=0;i<10;++i) {
  constexpr auto header=offsetof(FILE_ID_EXTD_DIR_INFO,FileName);
  if(at>sizeof(buffer)-header)break;
  const auto* entry=reinterpret_cast<const FILE_ID_EXTD_DIR_INFO*>(buffer+at);
  if(entry->FileNameLength>sizeof(buffer)-at-header || entry->FileNameLength%2)break;
  std::wstring name(entry->FileName,entry->FileNameLength/sizeof(WCHAR));
  std::printf("{\"enumeration_name\":\"%ls\",\"parent_id_same\":%s}\n",name.c_str(),std::memcmp(&entry->FileId,&expected.FileId,16)==0?"true":"false");
  if(!entry->NextEntryOffset)break;
  if(entry->NextEntryOffset%8 || entry->NextEntryOffset<header || entry->NextEntryOffset>sizeof(buffer)-at)break;
  at+=entry->NextEntryOffset;
 }
}
int wmain(int argc,wchar_t** argv) {
 if(argc!=2)return 2;std::wstring root=argv[1],a=root+L"\\a",b=root+L"\\b",child=a+L"\\child",moved=b+L"\\child";
 if(!CreateDirectoryW(root.c_str(),nullptr)||!CreateDirectoryW(a.c_str(),nullptr)||!CreateDirectoryW(b.c_str(),nullptr)||!CreateDirectoryW(child.c_str(),nullptr))return 3;
 {Handle marker{CreateFileW((child+L"\\marker").c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr)};if(marker.value==INVALID_HANDLE_VALUE)return 4;}
 Handle child_handle{directory(child)},parent_a{directory(a)},parent_b{directory(b)},volume{directory(L"V:\\")};
 if(child_handle.value==INVALID_HANDLE_VALUE||parent_a.value==INVALID_HANDLE_VALUE||parent_b.value==INVALID_HANDLE_VALUE||volume.value==INVALID_HANDLE_VALUE)return 5;
 dotdot(child_handle.value,parent_a.value,"before_move");enumerate(child_handle.value,parent_a.value);
 if(!MoveFileExW(child.c_str(),moved.c_str(),0))return 6;
 if(!CreateDirectoryW(child.c_str(),nullptr))return 7;
 dotdot(child_handle.value,parent_b.value,"after_move");enumerate(child_handle.value,parent_b.value);
 dotdot(volume.value,volume.value,"volume_root");
 return 0;
}

